// Independently composed environment studies. Geometry helpers do not build scenes.
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const r=(x,y,w,h,c,a='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}" ${a}/>`;
const p=(d,c='none',s='none',a='')=>`<path d="${d}" fill="${c}" stroke="${s}" ${a}/>`;
const poly=(d,c,s='none',a='')=>`<polygon points="${d}" fill="${c}" stroke="${s}" ${a}/>`;
const l=(x,y,x2,y2,c,a='')=>`<line x1="${x}" y1="${y}" x2="${x2}" y2="${y2}" stroke="${c}" ${a}/>`;
const e=(x,y,rx,ry,c,s='none',a='')=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${c}" stroke="${s}" ${a}/>`;
const t=(s,x,y,z=32,c='#efe7ff',a='')=>`<text x="${x}" y="${y}" font-family="Arial,Helvetica,sans-serif" font-size="${z}" fill="${c}" ${a}>${esc(s)}</text>`;
const serif=(s,x,y,z,c,a='')=>t(s,x,y,z,c,`font-family-override="Georgia" style="font-family:Georgia,serif" ${a}`);
const mono=(s,x,y,z=12,c='#bca3db',a='')=>t(s,x,y,z,c,`style="font-family:Menlo,Consolas,monospace" letter-spacing="2" ${a}`);
const g=(s,a='')=>`<g ${a}>${s}</g>`;
const repeat=(n,fn)=>Array.from({length:n},(_,i)=>fn(i)).join('');
const specks=(n,seed,c,box=[0,0,1440,900])=>{let z=seed;const rand=()=>((z=(z*1664525+1013904223)>>>0)/4294967296);return repeat(n,()=>{const x=box[0]+rand()*box[2],y=box[1]+rand()*box[3],s=rand()>.93?3:1;return r(x.toFixed(1),y.toFixed(1),s,s,c,`opacity="${(.12+rand()*.54).toFixed(2)}"`);});};
const grad=(id,a,b,x2='0',y2='1')=>`<linearGradient id="${id}" x2="${x2}" y2="${y2}"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
